const fn = new Function(code + "\nreturn { once };");
const { once } = fn();
let calls = 0;
const g = once((x) => { calls++; return x * 2; });
const a = g(21);
const b = g(100);
if (a !== 42) throw new Error("First call should return fn's result (42).");
if (b !== 42) throw new Error("Later calls must return the FIRST result, not re-run.");
if (calls !== 1) throw new Error("fn should have run exactly once.");

